  "q7_incompatible_technology": {
    "answer": "No",
    "evidence": "Study type: transcription profiling by array; 'Affymetrix U133A chips'; Technology: Array assay; Assay by Molecule: RNA assay.",
    "justification": "The technology is microarray expression profiling (compatible); not RNA-seq or proteomics."
  },
  "q8_inclusion_justification": {
    "justification": "Although this is a human microarray case/control study, it targets coronary artery disease and uses peripheral blood (leukocytes), not CNS tissue relevant to ALS-FTD. Therefore it fails the disease and tissue inclusion criteria and should be excluded."
